CREATE TYPE "DiscountType" AS ENUM ('PERCENTAGE','FIXED');
ALTER TABLE "Order" ADD COLUMN "discountMinor" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "shippingMinor" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "discountCode" VARCHAR(64), ADD COLUMN "shippingMethod" VARCHAR(80), ADD COLUMN "deliveryEstimateDays" INTEGER;
CREATE TABLE "Discount" ("id" TEXT PRIMARY KEY,"code" VARCHAR(64) NOT NULL UNIQUE,"type" "DiscountType" NOT NULL,"amount" INTEGER NOT NULL,"minimumOrderMinor" INTEGER NOT NULL DEFAULT 0,"usageLimit" INTEGER,"perCustomerLimit" INTEGER,"startsAt" TIMESTAMP(3),"expiresAt" TIMESTAMP(3),"isActive" BOOLEAN NOT NULL DEFAULT true,"usageCount" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "DiscountRedemption" ("id" TEXT PRIMARY KEY,"discountId" TEXT NOT NULL,"userId" TEXT NOT NULL,"orderId" TEXT NOT NULL UNIQUE,"amountMinor" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "DiscountRedemption_discountId_fkey" FOREIGN KEY ("discountId") REFERENCES "Discount"("id") ON DELETE RESTRICT, CONSTRAINT "DiscountRedemption_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT);
CREATE INDEX "Discount_isActive_expiresAt_idx" ON "Discount"("isActive","expiresAt"); CREATE INDEX "DiscountRedemption_discountId_userId_idx" ON "DiscountRedemption"("discountId","userId");
CREATE TABLE "CustomerAddress" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"firstName" VARCHAR(100) NOT NULL,"lastName" VARCHAR(100) NOT NULL,"phone" VARCHAR(16) NOT NULL,"addressLine1" VARCHAR(200) NOT NULL,"addressLine2" VARCHAR(200),"city" VARCHAR(100) NOT NULL,"province" VARCHAR(100) NOT NULL,"postalCode" CHAR(10) NOT NULL,"isDefault" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CustomerAddress_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE INDEX "CustomerAddress_userId_isDefault_idx" ON "CustomerAddress"("userId","isDefault");
CREATE TABLE "ShippingRate" ("id" TEXT PRIMARY KEY,"province" VARCHAR(100) NOT NULL UNIQUE,"method" VARCHAR(80) NOT NULL,"priceMinor" INTEGER NOT NULL,"estimatedDays" INTEGER NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL); CREATE INDEX "ShippingRate_isActive_province_idx" ON "ShippingRate"("isActive","province");
